    @GameTest(template="empty",timeoutTicks=180) public static void canceledPhysicalDropSaveReloadRetriesExactlyOneCrystal(GameTestHelper h){new Fixture(h).run(f->{var data=new CondenserDropData();data.add(f.pos,f.pos.getX()+.5,f.pos.getY()+.5,f.pos.getZ()+.5,AspectCrystalItem.create(Aspect.FLUX));Consumer<EntityJoinLevelEvent> veto=e->{if(e.getLevel()==f.level&&e.getEntity() instanceof ItemEntity item&&AspectCrystalItem.crystalAspect(item.getItem())==Aspect.FLUX)e.setCanceled(true);};MinecraftForge.EVENT_BUS.addListener(veto);CompoundTag image;try{data.tick(f.level);image=data.save(new CompoundTag());}finally{MinecraftForge.EVENT_BUS.unregister(veto);}h.assertTrue(data.pendingCount(f.pos)==1&&serialized(image)==1&&f.crystals()==0,"Canceled physical reward lost ownership");var loaded=CondenserDropData.load(image);loaded.tick(f.level);loaded.tick(f.level);h.assertTrue(loaded.pendingCount(f.pos)==0&&f.crystals()==1,"Reload lost or replayed a canceled crystal");});}
    @GameTest(template="empty",timeoutTicks=180) public static void acceptedConsumedOuterCanceledCrystalCannotRemainInSavedOwner(GameTestHelper h){new Fixture(h).run(f->{var data=new CondenserDropData();data.add(f.pos,f.pos.getX()+.5,f.pos.getY()+.5,f.pos.getZ()+.5,AspectCrystalItem.create(Aspect.FLUX));boolean[] once={false};CompoundTag[] image={null};Consumer<EntityJoinLevelEvent> callback=e->{if(!once[0]&&e.getLevel()==f.level&&e.getEntity() instanceof ItemEntity item&&AspectCrystalItem.crystalAspect(item.getItem())==Aspect.FLUX){once[0]=true;h.assertTrue(f.level.addFreshEntity(item)&&item.isAddedToWorld(),"Inner native crystal acceptance failed");item.discard();image[0]=data.save(new CompoundTag());data.tick(f.level);e.setCanceled(true);}};MinecraftForge.EVENT_BUS.addListener(callback);try{data.tick(f.level);}finally{MinecraftForge.EVENT_BUS.unregister(callback);}h.assertTrue(once[0]&&data.pendingCount(f.pos)==0&&serialized(image[0])==0&&f.crystals()==0,"Consumed/accepted crystal remained in live/saved owner");CondenserDropData.load(image[0]).tick(f.level);h.assertTrue(f.crystals()==0,"Consumed physical crystal replayed after reload");});}
    @GameTest(template="empty",timeoutTicks=180) public static void oldCatalogueMigrationRepairsOnlyEmptyTileAndRetainsPaidNativeReservoirs(GameTestHelper h){new Fixture(h).run(f->{var tile=f.line(1);var legacy=new CatalogBlockEntity(f.pos,tile.getBlockState());f.level.getChunkAt(f.pos).addAndRegisterBlockEntity(legacy);BlockPos other=f.pos.offset(3,0,0);f.block(other,CatalogBlocks.block("condenser").defaultBlockState());var paid=(CondenserBlockEntity)f.level.getBlockEntity(other);CompoundTag tag=new CompoundTag();tag.putShort("essentia",(short)17);tag.putShort("flux",(short)9);paid.load(tag);LegacyCondenserMigration.load(new ChunkEvent.Load(f.level.getChunkAt(f.pos),false));for(int i=0;i<200&&f.level.getBlockEntity(f.pos)==legacy;i++)LegacyCondenserMigration.tick(new TickEvent.LevelTickEvent(LogicalSide.SERVER,TickEvent.Phase.END,f.level,()->true));h.assertTrue(f.level.getBlockEntity(f.pos) instanceof CondenserBlockEntity repaired&&repaired.storedEssentia()==0&&repaired.storedFlux()==0&&legacy.isRemoved()&&f.level.getBlockEntity(other)==paid&&paid.storedEssentia()==17&&paid.storedFlux()==9,"Migration replaced paid native tile or invented reservoirs");var nbt=f.level.getChunkAt(f.pos).getBlockEntityNbtForSaving(f.pos);h.assertTrue(nbt!=null&&nbt.getString("id").equals("thaumcraft:condenser")&&BlockEntity.loadStatic(f.pos,f.level.getBlockState(f.pos),nbt) instanceof CondenserBlockEntity,"Repaired chunk persisted catalogue BE ID");});}
