    private static void unsupportedPlacement(GameTestHelper h,Fixture f,boolean creative){f.block(f.pos,Blocks.STONE.defaultBlockState());var player=f.player(creative);var stack=new ItemStack(CatalogBlocks.block("condenser_lattice"),2);player.setItemInHand(InteractionHand.MAIN_HAND,stack);BlockPos target=f.pos.above();f.states.putIfAbsent(target,f.level.getBlockState(target));var context=new UseOnContext(player,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(f.pos).add(0,.5,0),Direction.UP,f.pos,false));h.assertTrue(stack.useOn(context).consumesAction()&&stack.getCount()==(creative?2:1)&&f.level.getBlockState(target).is(CatalogBlocks.block("condenser_lattice")),"Modern unsupported placement failed before physical paid block ownership");((CondenserLatticeBlock)CatalogBlocks.block("condenser_lattice")).tick(f.level.getBlockState(target),f.level,target,f.level.random);var data=CondenserDropData.get(f.level);h.assertTrue(f.level.getBlockState(target).isAir()&&data.pendingCount(target)==1,"Unsupported paid block missing physical ledger owner");data.tick(f.level);h.assertTrue(f.items(CatalogBlocks.block("condenser_lattice").asItem())==1&&data.pendingCount(target)==0&&stack.getCount()==(creative?2:1),"Unsupported native placement duplicated/lost survival debit or originalcreative drop");}
    @GameTest(template="empty",timeoutTicks=180) public static void supportedLatticeSixRodShapeConnectionsAndOriginalLightRemainNative(GameTestHelper h){new Fixture(h).run(f->{f.line(2);f.lattice(f.pos.above().east(),false);BlockState state=f.level.getBlockState(f.pos.above());h.assertTrue(state.getValue(CondenserLatticeBlock.DOWN)&&state.getValue(CondenserLatticeBlock.UP)&&state.getValue(CondenserLatticeBlock.EAST)&&!state.getValue(CondenserLatticeBlock.WEST)&&state.getLightEmission(f.level,f.pos.above())==4,"Original connected rods/cleanlight changed");var box=state.getShape(f.level,f.pos.above()).bounds();h.assertTrue(box.minY==0&&box.maxY==1&&box.maxX==1&&box.minX==.3125&&box.minZ==.3125&&box.maxZ==.6875,"Original indexed rod selection bounding box changed");});}
    @GameTest(template="empty",timeoutTicks=240) public static void registeredServerTickerUsesActualWorldTicksAndRedstonePause(GameTestHelper h){
        var f=new Fixture(h);f.enableWorldTicks();CondenserBlockEntity[] tile={null};AlembicBlockEntity[] source={null};int[] before={0};
        h.startSequence().thenWaitUntil(()->h.assertTrue(f.level.getChunkSource().isPositionTicking(new ChunkPos(f.pos).toLong()),"Native fixture ticket has not reached BLOCK_TICKING"))
            .thenExecute(()->{f.originalFlux=AuraManager.getFlux(f.level,f.pos);tile[0]=f.line(1);source[0]=f.source(Direction.SOUTH,Aspect.AIR,8);f.block(f.pos.east(),Blocks.REDSTONE_BLOCK.defaultBlockState());})
            .thenIdle(12).thenExecute(()->{try{h.assertTrue(tile[0].ticks()>=10&&tile[0].storedEssentia()==0&&source[0].amount()==8&&!tile[0].getBlockState().getValue(CondenserBlock.ENABLED),"Registered powered BE ticker failed native pause: ticks="+tile[0].ticks()+", power="+tile[0].storedEssentia()+", source="+source[0].amount()+", enabled="+tile[0].getBlockState().getValue(CondenserBlock.ENABLED));before[0]=tile[0].ticks();f.block(f.pos.east(),Blocks.AIR.defaultBlockState());}catch(RuntimeException|Error failure){f.close();throw failure;}})
            .thenIdle(20).thenExecute(()->{try{int power=tile[0].storedEssentia();h.assertTrue(tile[0].ticks()-before[0]>=19&&power>=3&&power<=5&&source[0].amount()+power==8&&tile[0].getBlockState().getValue(CondenserBlock.ENABLED),"Registered native BE ticker failed physical pulls: elapsed="+(tile[0].ticks()-before[0])+", power="+power+", source="+source[0].amount()+", enabled="+tile[0].getBlockState().getValue(CondenserBlock.ENABLED));}finally{f.close();}}).thenSucceed();
    }
