    @GameTest(template="empty",timeoutTicks=180) public static void nativeTransportSnapshotRollbackRestoresOnlyReservoirsAndKeepsTransientTopology(GameTestHelper h){new Fixture(h).run(f->{var tile=f.line(2);f.reservoirs(tile,17,3);f.ticks(tile,13);CompoundTag snapshot=tile.saveWithoutMetadata();h.assertTrue(tile.takeEssentia(Aspect.FLUX,1,Direction.DOWN)==1,"Native payment seed failed");tile.restoreTransportSnapshot(snapshot);h.assertTrue(tile.storedFlux()==3&&tile.storedEssentia()==17&&tile.ticks()==13&&tile.interval()==575&&tile.cost()==5&&tile.cleanLatticePositions().size()==2,"Guarded rollback applied load and reset unsaved state");f.block(f.pos,Blocks.AIR.defaultBlockState());tile.restoreTransportSnapshot(snapshot);h.assertTrue(tile.storedFlux()==0&&tile.storedEssentia()==0,"Removed paid endpoint was resurrected by snapshot rollback");});}
    @GameTest(template="empty",timeoutTicks=180) public static void lowerThanBaseLatticeCanHaveSupportButNeverContributesProcessingNodes(GameTestHelper h){new Fixture(h).run(f->{var tile=f.line(1);f.lattice(f.pos.above().east(),false);f.lattice(f.pos.east(),false);f.lattice(f.pos.east().below(),false);tile.triggerCheck();h.assertTrue(tile.connectedLatticeCount()==2&&!tile.cleanLatticePositions().contains(f.pos.east())&&!tile.cleanLatticePositions().contains(f.pos.east().below()),"Separate support DFS admitted below-base nodes to power topology");for(BlockPos p:List.of(f.pos.east(),f.pos.east().below()))((CondenserLatticeBlock)CatalogBlocks.block("condenser_lattice")).tick(f.level.getBlockState(p),f.level,p,f.level.random);h.assertTrue(f.level.getBlockState(f.pos.east()).is(CatalogBlocks.block("condenser_lattice"))&&f.level.getBlockState(f.pos.east().below()).is(CatalogBlocks.block("condenser_lattice")),"Connected below-base support was incorrectly dropped");});}
