    @GameTest(template="empty",timeoutTicks=180) public static void disabledBlockDropsSuppressesSupportLootButNotOriginalDirectFilterCrystal(GameTestHelper h){new Fixture(h).run(f->{boolean before=f.level.getGameRules().getBoolean(GameRules.RULE_DOBLOCKDROPS);f.level.getGameRules().getRule(GameRules.RULE_DOBLOCKDROPS).set(false,f.level.getServer());try{f.lattice(f.pos,false);((CondenserLatticeBlock)CatalogBlocks.block("condenser_lattice")).tick(f.level.getBlockState(f.pos),f.level,f.pos,f.level.random);h.assertTrue(f.level.getBlockState(f.pos).isAir()&&CondenserDropData.get(f.level).pendingCount(f.pos)==0&&f.items(CatalogBlocks.block("condenser_lattice").asItem())==0,"Unsupported native block ignored doTileDrops=false");f.line(1);f.lattice(f.pos.above(),true);var player=f.player(false);player.setItemInHand(InteractionHand.MAIN_HAND,CatalogModule.stack("filter"));f.level.random.setSeed(0);h.assertTrue(f.clean(player,f.pos.above(),Direction.EAST).consumesAction(),"Filter cleanup incorrectly followed block-loot gamerule");CondenserDropData.get(f.level).tick(f.level);h.assertTrue(f.crystals()==1,"Direct original filter crystal was suppressed with blockloot");}finally{f.level.getGameRules().getRule(GameRules.RULE_DOBLOCKDROPS).set(before,f.level.getServer());}});}
    @GameTest(template="empty",timeoutTicks=180) public static void canceledNativeLatticePlacementNeverCreatesUnpaidSupportLoot(GameTestHelper h){new Fixture(h).run(f->{f.block(f.pos,Blocks.STONE.defaultBlockState());var player=f.player(false);var stack=new ItemStack(CatalogBlocks.block("condenser_lattice"),2);player.setItemInHand(InteractionHand.MAIN_HAND,stack);BlockPos target=f.pos.above();f.states.putIfAbsent(target,f.level.getBlockState(target));Consumer<BlockEvent.EntityPlaceEvent> veto=e->{if(e.getEntity()==player)e.setCanceled(true);};MinecraftForge.EVENT_BUS.addListener(veto);try{var context=new UseOnContext(player,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(f.pos).add(0,.5,0),Direction.UP,f.pos,false));h.assertTrue(!stack.useOn(context).consumesAction(),"Canceled actual BlockItem placement committed");}finally{MinecraftForge.EVENT_BUS.unregister(veto);}((CondenserLatticeBlock)CatalogBlocks.block("condenser_lattice")).tick(f.level.getBlockState(target),f.level,target,f.level.random);CondenserDropData.get(f.level).tick(f.level);h.assertTrue(stack.getCount()==2&&f.level.getBlockState(target).isAir()&&CondenserDropData.get(f.level).pendingCount(target)==0&&f.items(CatalogBlocks.block("condenser_lattice").asItem())==0,"Canceled unpaid BlockItem created ghost support loot");});}
    @GameTest(template="empty",timeoutTicks=180) public static void foreignRemovalDuringNativePlacementCannotCreateDeferredGhostBlock(GameTestHelper h){new Fixture(h).run(f->{f.block(f.pos,Blocks.STONE.defaultBlockState());var player=f.player(false);var stack=new ItemStack(CatalogBlocks.block("condenser_lattice"),2);player.setItemInHand(InteractionHand.MAIN_HAND,stack);BlockPos target=f.pos.above();f.states.putIfAbsent(target,f.level.getBlockState(target));Consumer<BlockEvent.EntityPlaceEvent> callback=e->{if(e.getEntity()==player)f.level.setBlock(target,Blocks.AIR.defaultBlockState(),3);};MinecraftForge.EVENT_BUS.addListener(callback);try{var context=new UseOnContext(player,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(f.pos).add(0,.5,0),Direction.UP,f.pos,false));h.assertTrue(!stack.useOn(context).consumesAction(),"Foreign removed uncommitted placement still paid its hand");}finally{MinecraftForge.EVENT_BUS.unregister(callback);}((CondenserLatticeBlock)CatalogBlocks.block("condenser_lattice")).tick(f.level.getBlockState(target),f.level,target,f.level.random);CondenserDropData.get(f.level).tick(f.level);h.assertTrue(stack.getCount()==2&&f.level.getBlockState(target).isAir()&&CondenserDropData.get(f.level).pendingCount(target)==0&&f.items(CatalogBlocks.block("condenser_lattice").asItem())==0,"Foreign removed unpaid placement generated a deferred physical block or hand debit");});}
    @GameTest(template="empty",timeoutTicks=180) public static void unloadedBoundaryTopologyAndShapeNeverPromoteAdjacentChunk(GameTestHelper h){new Fixture(h).run(f->{BlockPos at=null;for(int i=0;i<16;i++){int x=120000+3*i;f.level.getChunk(x,120000);BlockPos p=new BlockPos((x<<4)+15,230,(120000<<4)+8);if(f.level.getChunkSource().getChunkNow(x+1,120000)==null){at=p;break;}}h.assertTrue(at!=null,"Could not establish an actual unloaded edge fixture");
        // Captured raw placement separates device reads from vanilla's own unconditional neighbor notifications.
        boolean capture=f.level.captureBlockSnapshots;int start=f.level.capturedBlockSnapshots.size();f.level.captureBlockSnapshots=true;BlockPos sourcePos=at.west();
        try{f.block(at,CatalogBlocks.block("condenser").defaultBlockState());f.lattice(at.above(),false);f.block(sourcePos,CatalogBlocks.block("alembic").defaultBlockState());}finally{if(f.level.capturedBlockSnapshots.size()>start)f.level.capturedBlockSnapshots.subList(start,f.level.capturedBlockSnapshots.size()).clear();f.level.captureBlockSnapshots=capture;}
        int edgeX=(at.getX()>>4)+1,edgeZ=at.getZ()>>4;
        h.assertTrue(f.level.getChunkSource().getChunkNow(edgeX,edgeZ)==null,"Captured native placement promoted the adjacent edge before device reads");
        var tile=(CondenserBlockEntity)f.level.getBlockEntity(at);var source=(AlembicBlockEntity)f.level.getBlockEntity(sourcePos);
        h.assertTrue(!tile.getBlockState().isRedstoneConductor(f.level,at),"Released non-full condenser became a vanilla redstone/comparator conductor");
        source.addToContainer(Aspect.AIR,3);
        h.assertTrue(f.level.getChunkSource().getChunkNow(edgeX,edgeZ)==null,"Native physical Alembic funding promoted the adjacent edge through the condenser");
        tile.triggerCheck();h.assertTrue(tile.latticeCount()==-1&&f.level.getChunkSource().getChunkNow(edgeX,edgeZ)==null,"Loaded-only topology check promoted an unavailable edge: weight="+tile.latticeCount());
        f.ticks(tile,10);f.level.getBlockState(at.above()).getShape(f.level,at.above());
        Boolean power=CondenserBlock.loadedPower(f.level,at);boolean edgeLoaded=f.level.getChunkSource().getChunkNow(edgeX,edgeZ)!=null;
        h.assertTrue(power==null&&tile.latticeCount()==-1&&tile.ticks()==10&&tile.storedEssentia()==0&&source.amount()==3&&!edgeLoaded,"Unavailable graph/power/shape changed ownership: power="+power+", weight="+tile.latticeCount()+", ticks="+tile.ticks()+", reservoir="+tile.storedEssentia()+", source="+source.amount()+", edgeLoaded="+edgeLoaded);});}
    @GameTest(template="empty",timeoutTicks=180) public static void genuinelyMissingLegacyTileIsFoundInChunkSectionsAndSavedAsNativeDevice(GameTestHelper h){new Fixture(h).run(f->{var old=f.line(1);var chunk=f.level.getChunkAt(f.pos);chunk.removeBlockEntity(f.pos);h.assertTrue(old.isRemoved()&&!chunk.getBlockEntitiesPos().contains(f.pos)&&chunk.getBlockEntity(f.pos,net.minecraft.world.level.chunk.LevelChunk.EntityCreationType.CHECK)==null,"No-tile fixture accidentally retained a catalogue/native anchor");BlockPos other=f.pos.offset(3,0,0);f.block(other,CatalogBlocks.block("condenser").defaultBlockState());var paid=(CondenserBlockEntity)f.level.getBlockEntity(other);CompoundTag tag=new CompoundTag();tag.putShort("essentia",(short)17);tag.putShort("flux",(short)9);paid.load(tag);
        LegacyCondenserMigration.load(new ChunkEvent.Load(chunk,false));for(int i=0;i<200&&chunk.getBlockEntity(f.pos,net.minecraft.world.level.chunk.LevelChunk.EntityCreationType.CHECK)==null;i++)LegacyCondenserMigration.tick(new TickEvent.LevelTickEvent(LogicalSide.SERVER,TickEvent.Phase.END,f.level,()->true));var repaired=chunk.getBlockEntity(f.pos,net.minecraft.world.level.chunk.LevelChunk.EntityCreationType.CHECK);
        h.assertTrue(repaired instanceof CondenserBlockEntity tile&&tile.getType()==CondenserModule.CONDENSER.get()&&tile.storedEssentia()==0&&tile.storedFlux()==0&&f.level.getBlockEntity(other)==paid&&paid.storedEssentia()==17&&paid.storedFlux()==9,"Section scan missed absent legacy tile or replaced paid native reservoir");var nbt=chunk.getBlockEntityNbtForSaving(f.pos);h.assertTrue(nbt!=null&&nbt.getString("id").equals("thaumcraft:condenser")&&BlockEntity.loadStatic(f.pos,f.level.getBlockState(f.pos),nbt) instanceof CondenserBlockEntity,"Absent old tile repair did not survive an actual chunk-NBT reload");});}
    @GameTest(template="empty",timeoutTicks=180) public static void actualCanceledForgePlaceCallbackCannotTickUnpaidLatticeOrCondenser(GameTestHelper h){new Fixture(h).run(f->{f.block(f.pos,Blocks.STONE.defaultBlockState());BlockPos target=f.pos.above();f.states.putIfAbsent(target,f.level.getBlockState(target));var player=f.player(false);int[] callbacks={0};CondenserBlockEntity[] captured={null};Consumer<BlockEvent.EntityPlaceEvent> callback=e->{if(e.getEntity()!=player)return;callbacks[0]++;h.assertTrue(!f.level.captureBlockSnapshots&&CondenserBlockItem.uncommitted(f.level,target),"Native capture=false place callback did not hold a pending unpaid receipt");BlockState state=f.level.getBlockState(target);
            if(state.getBlock() instanceof CondenserLatticeBlock lattice)lattice.tick(state,f.level,target,f.level.random);
            if(f.level.getBlockEntity(target) instanceof CondenserBlockEntity tile){captured[0]=tile;for(int i=0;i<5;i++)CondenserBlockEntity.tick(f.level,target,state,tile);}e.setCanceled(true);
        };MinecraftForge.EVENT_BUS.addListener(callback);
        try{var lattice=new ItemStack(CatalogBlocks.block("condenser_lattice"),2);player.setItemInHand(InteractionHand.MAIN_HAND,lattice);var context=new UseOnContext(player,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(f.pos).add(0,.5,0),Direction.UP,f.pos,false));h.assertTrue(!lattice.useOn(context).consumesAction()&&lattice.getCount()==2&&f.level.getBlockState(target).isAir()&&CondenserDropData.get(f.level).pendingCount(target)==0,"Canceled captured lattice callback created unpaid physical output");
            f.lattice(target.above(),false);BlockPos sourcePos=target.south();f.block(sourcePos,CatalogBlocks.block("alembic").defaultBlockState());var source=(AlembicBlockEntity)f.level.getBlockEntity(sourcePos);source.addToContainer(Aspect.AIR,4);var condenser=new ItemStack(CatalogBlocks.block("condenser"),2);player.setItemInHand(InteractionHand.MAIN_HAND,condenser);
            var secondContext=new UseOnContext(player,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(f.pos).add(0,.5,0),Direction.UP,f.pos,false));h.assertTrue(!condenser.useOn(secondContext).consumesAction()&&condenser.getCount()==2&&f.level.getBlockState(target).isAir()&&source.amount()==4&&captured[0]!=null&&captured[0].ticks()==0&&captured[0].storedEssentia()==0&&callbacks[0]==2,"Canceled pending condenser tick paid essence/count before physical BlockItem commit");
        }finally{MinecraftForge.EVENT_BUS.unregister(callback);}CondenserDropData.get(f.level).tick(f.level);h.assertTrue(f.items(CatalogBlocks.block("condenser_lattice").asItem())==0,"Canceled captured support callback retained a ghost item after retry");});}
